#include "papinho_secure_transport.h"
#include "papinho_secure_transport_win32.h"
#include <stdio.h>
#include <string.h>
#define CHECK(x) if(!(x)){printf("test_public_combined_selection: FAIL line %d\n",__LINE__);return 1;}
static PST_RESULT make_runtime(pst_u32 selection,const char*exact,const char*const*ordered,pst_size count,pst_u32 caps,pst_runtime**out){PST_RUNTIME_OPTIONS o;memset(&o,0,sizeof(o));o.struct_size=sizeof(o);o.api_version=PST_API_VERSION;o.selection=selection;o.exact_backend_id=exact;o.preferred_backend_ids=ordered;o.preferred_backend_count=count;o.required_capabilities=caps;return pst_runtime_create(&o,out);}
static int is_backend(pst_runtime*r,const char*id){PST_RUNTIME_INFO i;memset(&i,0,sizeof(i));i.struct_size=sizeof(i);i.api_version=PST_API_VERSION;return pst_runtime_get_info(r,&i)==PST_RESULT_OK&&!strcmp(i.backend_id,id);}
int main(void){pst_runtime*r=NULL;const char*order[2];pst_u32 tls12=PST_CAP_TLS_1_2|PST_CAP_SYSTEM_TRUST; pst_u32 tls13=PST_CAP_TLS_1_3|PST_CAP_SYSTEM_TRUST;CHECK(pst_win32_register_builtin_providers()==PST_RESULT_OK);CHECK(make_runtime(PST_BACKEND_SELECTION_AUTOMATIC,NULL,NULL,0,tls12,&r)==PST_RESULT_OK&&is_backend(r,"schannel"));pst_runtime_release(r);r=NULL;CHECK(make_runtime(PST_BACKEND_SELECTION_AUTOMATIC,NULL,NULL,0,tls13,&r)==PST_RESULT_OK&&is_backend(r,"openssl"));pst_runtime_release(r);r=NULL;CHECK(make_runtime(PST_BACKEND_SELECTION_EXACT,"openssl",NULL,0,tls13,&r)==PST_RESULT_OK&&is_backend(r,"openssl"));pst_runtime_release(r);r=NULL;CHECK(make_runtime(PST_BACKEND_SELECTION_EXACT,"schannel",NULL,0,tls13,&r)==PST_RESULT_UNSUPPORTED&&!r);order[0]="openssl";order[1]="schannel";CHECK(make_runtime(PST_BACKEND_SELECTION_ORDERED,NULL,order,2,tls12,&r)==PST_RESULT_OK&&is_backend(r,"openssl"));pst_runtime_release(r);printf("PUBLIC_COMBINED_SELECTION TLS12_SYSTEM_AUTO=schannel TLS13_SYSTEM_AUTO=openssl EXACT_OPENSSL_TLS13=PASS EXACT_SCHANNEL_TLS13=UNSUPPORTED ORDERED_OPENSSL_FIRST_TLS12=openssl PASS=1\n");return 0;}